/* ===========================
   Title
=========================== */
.web-form h1 {
    font-size: 28px;
    font-weight: 700;
    color: #2c3e50;
    margin-bottom: 25px;
}

/* ===========================*/
/*   Form Groups*/
/*=========================== */
.web-form .form-group {
    margin-bottom: 20px;
    text-align: left;
}

 /*Labels */
.web-form label {
    font-weight: 600;
    margin-bottom: 6px;
    display: block;
    color: #333;
}

 /*Text and Textarea Fields */
.web-form .form-control {
    width: 100%;
    padding: 12px 14px;
    border: 1px solid #ccc;
    border-radius: 10px;
    font-size: 15px;
    transition: all 0.3s ease;
    color: #333;
}

.web-form .form-control:focus {
    border-color: #007bff;
    box-shadow: 0 0 6px rgba(0, 123, 255, 0.3);
    outline: none;
}

 /*Textareas */
.web-form textarea.form-control {
    min-height: 100px;
    resize: vertical;
}

/* ===========================*/
/*   Select / Dropdown Fields*/
/*=========================== */
 /*Link-style dropdowns like Assigned To */
.web-form select.form-control {
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    width: 100%;
    min-height: 38px;
    line-height: 1.6;
    border: 1px solid #ccc;
    border-radius: 5px;
    padding: 8px 12px;
    font-size: 14px;
    color: #333;
    background: #f5f5f5 url("data:image/svg+xml;charset=US-ASCII,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8'><polygon points='0,0 12,0 6,8' style='fill:%23666;'/></svg>") no-repeat right 12px center;
    background-size: 12px;
    cursor: pointer;
    transition: all 0.3s ease;
}

 /*On focus, highlight like Assigned To */
.web-form select.form-control:focus {
    background: #fff;
    border-color: #007bff;
    box-shadow: 0 0 6px rgba(0,123,255,0.3);
    outline: none;
}


/* ===========================*/
/*   Link Fields (Resident, Assigned To)*/
/*=========================== */
.web-form .form-control[data-fieldtype="Link"] {
    min-height: 38px;
    line-height: 1.6;
    color: #333;
    padding: 8px 12px;
}

/* ===========================*/
/*   Button Group Centered*/
/*=========================== */
.web-form .form-actions {
    display: flex;
    justify-content: center;
    gap: 15px;
    margin-top: 20px;
}

/* ===========================*/
/*   Buttons*/
/*=========================== */

/* Save Button */
.web-form .btn-primary {
    background: linear-gradient(45deg, #007bff, #00c6ff);
    border: none;
    border-radius: 12px;
    padding: 12px 30px;
    font-size: 16px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.web-form .btn-primary:hover {
    background: linear-gradient(45deg, #0056b3, #0096c7);
    box-shadow: 0 6px 20px rgba(0, 123, 255, 0.3);
    transform: translateY(-2px);
}

 /*Discard / Secondary Button */
.web-form .btn-secondary {
    border-radius: 12px;
    padding: 12px 30px;
    font-size: 16px;
    font-weight: 600;
    background: #f1f1f1;
    border: none;
    transition: all 0.3s ease;
}

.web-form .btn-secondary:hover {
    background: #e0e0e0;
    transform: translateY(-2px);
}

/* ===========================*/
/*   Responsive*/
/*=========================== */
@media (max-width: 640px) {
    .web-form {
        padding: 20px;
        margin: 20px 15px;
    }
}
